package calc

import (
	"errors"
	"testing"
)

// The native flavor's parser, generated by the real galop, parses input.
func TestParse(t *testing.T) {
	prog, err := ParseProg(CalcLex("1 + 22 - 3"))
	if err != nil {
		t.Fatal(err)
	}
	if got := len(prog.Expr().AllINT()); got != 3 {
		t.Errorf("INT tokens: got %d, want 3", got)
	}
	if got, want := prog.ToStringTree(), "(prog (expr 1 + 22 - 3) <EOF>)"; got != want {
		t.Errorf("tree: got %s, want %s", got, want)
	}
}

func TestSyntaxError(t *testing.T) {
	_, err := ParseProg(CalcLex("1 +"))
	var se *CalcSyntaxError
	if !errors.As(err, &se) {
		t.Fatalf("got %v (%T), want a *CalcSyntaxError", err, err)
	}
}
